  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, metric, value, service_name FROM abnormal_metrics WHERE service_name='profile' AND metric IN ('k8s.deployment.available','k8s.deployment.desired') ORDER BY time", "claim": "Profile deployment availability drops from 1 to 0 about 12:20:45 and stays 0 through the window end."},
        {"kind": "trace", "sql": "SELECT (SELECT count(*) FROM normal_traces WHERE service_name='profile') AS normal_profile_spans, (SELECT count(*) FROM abnormal_traces WHERE service_name='profile') AS abnormal_profile_spans", "claim": "Profile emits about 4750 spans in the normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT attr_status_code, count(*) n, round(approx_quantile(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' AND attr_span_kind='Client' GROUP BY 1", "claim": "Frontend calls to profile fail with Error status in about 0.01 ms, with no profile-side spans."}
      ]
    }
  ],
  "propagation": [
    {"from": "profile", "to": "frontend",
     "evidence": [
       {"kind": "trace", "sql": "SELECT s.span_name, s.attr_status_code, s.attr_http_response_status_code, c.span_name AS child_span, c.service_name AS child_service, c.attr_status_code AS child_status, count(*) n FROM abnormal_traces s JOIN abnormal_traces c ON c.parent_span_id = s.span_id AND c.trace_id = s.trace_id WHERE s.service_name='frontend' AND s.span_name='HTTP /hotels' AND c.span_name='profile.Profile/GetProfiles' GROUP BY ALL", "claim": "Frontend HTTP /hotels requests return 500 whenever their profile.Profile/GetProfiles child call errors."}
     ]}
  ]
}
